<?php
declare(strict_types=1);
use App\Domain\JournalFeed;
use App\Support\Html;
use App\Support\Language;
/** @var Language $lang */
/** @var list<array<string,mixed>> $journal */
?>
<section class="page-hero shell"><span class="eyebrow">CURRENT / CHANGELOG / DECISIONS</span><h1><?= $lang->value('Vývojový deník.','Workshop log.') ?></h1><p><?= $lang->value('Průběžný záznam toho, co stavím, měním a proč. Bez automaticky generovaných superlativů.', 'A running record of what I am building, what changed and why. No autogenerated superlatives.') ?></p></section>
<section class="section shell"><div class="journal-timeline"><?php foreach ($journal as $entry): $source = Html::safeUrl((string)($entry['source_url'] ?? '')); $entryId = JournalFeed::entryId($entry); ?><article class="timeline-item" id="<?= Html::escape($entryId) ?>"><div class="timeline-marker"></div><time><?= Html::escape(substr((string)$entry['published_at'],0,10)) ?></time><div class="timeline-copy"><span class="category"><?= Html::escape((string)$entry['category']) ?></span><h2><a href="#<?= Html::escape($entryId) ?>"><?= Html::escape((string)$entry['title_'.$lang->code]) ?></a></h2><p><?= Html::escape((string)$entry['body_'.$lang->code]) ?></p><?php if ($source !== '#'): ?><a class="inline-link" href="<?= Html::escape($source) ?>" target="_blank" rel="noopener noreferrer">SOURCE ↗</a><?php endif; ?></div></article><?php endforeach; ?></div></section>
